begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('a5700000-0000-4000-8000-000000000001'),('a5700000-0000-4000-8000-000000000002'),('a5700000-0000-4000-8000-000000000003');
insert into profiles(id,display_name,consented_at) select id,'Admin boundary fixture',now() from auth.users where id::text like 'a5700000-%';
insert into families(id,name) values('a5700000-0000-4000-8000-000000000010','Admin fixture family');
insert into family_members(family_id,user_id,role) values('a5700000-0000-4000-8000-000000000010','a5700000-0000-4000-8000-000000000001','owner');
insert into children(id,family_id,name,sex,birth_date) values('a5700000-0000-4000-8000-000000000011','a5700000-0000-4000-8000-000000000010','PRIVATE_CHILD_NAME','female',current_date);
insert into child_records(id,child_id,service,kind,title,occurred_at,record_timezone,created_by,updated_by,created_at) values('a5700000-0000-4000-8000-000000000020','a5700000-0000-4000-8000-000000000011','growth','observation','PRIVATE_DIARY_BODY',now(),'UTC','a5700000-0000-4000-8000-000000000001','a5700000-0000-4000-8000-000000000001',now()-interval '2 days');
insert into care_records(id,child_id,kind,started_at,record_timezone,created_by,updated_by,created_at) values('a5700000-0000-4000-8000-000000000021','a5700000-0000-4000-8000-000000000011','formula',now(),'UTC','a5700000-0000-4000-8000-000000000001','a5700000-0000-4000-8000-000000000001',now()-interval '1 day');
insert into child_records(id,child_id,service,kind,occurred_at,record_timezone,created_by,updated_by) values('a5700000-0000-4000-8000-000000000022','a5700000-0000-4000-8000-000000000011','diaper','wet',now(),'UTC','a5700000-0000-4000-8000-000000000002','a5700000-0000-4000-8000-000000000002');
insert into developer_requests(id,user_id,category,body) values('a5700000-0000-4000-8000-000000000030','a5700000-0000-4000-8000-000000000002','feature','Requester body');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select ok(not is_service_admin(),'family owner is not a service admin');
select throws_ok($$select admin_dashboard()$$,'42501','forbidden','normal signed-in users cannot read the service dashboard');
select throws_ok($$insert into service_admins(user_id) values(auth.uid())$$,'42501',null,'users cannot grant themselves service admin');
reset role;
insert into community_moderators(user_id) values('a5700000-0000-4000-8000-000000000001');
set local role authenticated;
select throws_ok($$select admin_dashboard()$$,'42501','forbidden','community moderator does not gain service access');
reset role;
insert into service_admins(user_id) values('a5700000-0000-4000-8000-000000000001');
set local role authenticated;
select ok(is_service_admin(),'designated operator has service access');
select ok(service_admin_access(),'designated operator can read admin data at aal1 without a factor');
select lives_ok($$select admin_requests()$$,'designated operator can read requests without MFA');
select is((admin_dashboard()->>'steady_families_7d')::int,1,'steady family includes three days across care types');
select is((admin_dashboard()->>'collaborating_families_7d')::int,1,'collaboration counts distinct record creators');
select is((admin_dashboard()->>'records_7d')::int,3,'feeding and child records are counted once');
select ok(admin_dashboard()::text not like '%PRIVATE_CHILD_NAME%' and admin_dashboard()::text not like '%PRIVATE_DIARY_BODY%','dashboard contains no private child content');
select is((admin_usage(7)->'daily'->0->>'records') is not null,true,'usage returns daily aggregates');
select is(jsonb_array_length(admin_usage(14)->'daily'),14,'daily series includes zero days');
select throws_ok($$select admin_usage(100000)$$,'22023','invalid period','unbounded analytics periods are rejected');
select is((select count(*)::int from admin_requests()),1,'operator reads received requests');
select lives_ok($$select admin_update_request('a5700000-0000-4000-8000-000000000030','in_progress','high','INTERNAL_ONLY_NOTE',0)$$,'operator updates status and private note');
select is((select version from admin_requests() where id='a5700000-0000-4000-8000-000000000030'),1,'request edit increments version');
select throws_ok($$select admin_update_request('a5700000-0000-4000-8000-000000000030','done','normal','old',0)$$,'40001','conflict','stale operator edits are rejected');
select is((select count(*)::int from admin_audit() where action='request_update'),1,'request edit creates an audit record');
select ok((select details::text not like '%INTERNAL_ONLY_NOTE%' from admin_audit() where action='request_update'),'audit excludes private note text');
select throws_ok($$select * from admin_request_details$$,'42501',null,'operators also use guarded RPCs for private notes');
select ok(admin_operations()::text not like '%PRIVATE_CHILD_NAME%','operations does not expose child names');
select is((select count(*)::int from admin_users()),3,'user list returns account metadata');
select is((select children::int from admin_families() where id='a5700000-0000-4000-8000-000000000010'),1,'family list returns counts');
select set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select status from developer_requests where id='a5700000-0000-4000-8000-000000000030'),'in_progress','request owner can still see public status');
select throws_ok($$select * from admin_request_details$$,'42501',null,'request owner cannot read internal notes');
select throws_ok($$select admin_update_request('a5700000-0000-4000-8000-000000000030','done','urgent','tamper',1)$$,'42501','forbidden','request owner cannot manage admin state');
select lives_ok($$select report_service_error('a5700000-0000-4000-8000-000000000050','today','render_failed','12345')$$,'signed-in users can report an allowlisted error');
select throws_ok($$select report_service_error(gen_random_uuid(),'today','PRIVATE_FORM_VALUE',null)$$,'23514',null,'raw error strings are not accepted');
select throws_ok($$select report_service_error(gen_random_uuid(),'share/token/private','render_failed',null)$$,'23514',null,'URLs and shared tokens cannot enter section field');
select throws_ok($$select report_service_error(gen_random_uuid(),'today','render_failed','private-name')$$,'23514',null,'raw strings are not accepted as error digests');
select throws_ok($$select * from service_error_events$$,'42501',null,'users cannot enumerate error reports');
select set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is((select count(*)::int from admin_errors()),1,'operator sees sanitized error reports');
select lives_ok($$select admin_resolve_error('a5700000-0000-4000-8000-000000000050')$$,'operator marks an error resolved');
select is((select count(*)::int from admin_errors()),0,'resolved errors leave the open list');
select is((select count(*)::int from admin_errors(false)),1,'resolved error history is available');
select is((select count(*)::int from admin_audit() where action in ('request_update','error_resolve')),2,'error resolution is audited');
reset role;
insert into developer_requests(id,user_id,category,body,created_at)
select gen_random_uuid(),'a5700000-0000-4000-8000-000000000002','bug','Pagination fixture',now() from generate_series(1,35);
set local role authenticated;
select is((select count(*)::int from admin_requests()),31,'request page fetches one extra row for pagination');
select is((with first_page as (select id,created_at from admin_requests() limit 30), cursor_row as (select * from first_page order by created_at,id limit 1), next_page as (select n.id from cursor_row c cross join lateral admin_requests('','',c.created_at,c.id) n) select count(*)::int from next_page),6,'identical timestamps paginate without missing rows');
select set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select report_service_error(gen_random_uuid(),'today','render_failed',null) from generate_series(1,25);
reset role;
select is((select count(*)::int from service_error_events where user_id='a5700000-0000-4000-8000-000000000002'),20,'error reporting stops at twenty per user per hour');
select is((select count(*)::int from admin_audit_log where action='admin_grant'),1,'trusted role assignment is audited');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select admin_dashboard()$$,'designated account remains accessible without an MFA factor');
reset role;
delete from service_admins where user_id='a5700000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select admin_dashboard()$$,'42501','forbidden','revoking operator role takes effect immediately');
reset role;
select ok(not has_function_privilege('anon','public.admin_dashboard()','execute'),'anonymous cannot execute admin dashboard');
select ok(not has_function_privilege('authenticated','public.cleanup_admin_logs()','execute'),'users cannot delete audit history');
select * from finish();
rollback;
